import csv, json
from pathlib import Path
import xml.etree.ElementTree as ET

HW_DIR = Path('/tmp/hwpx_work')
sec0 = HW_DIR/'Contents'/'section0.xml'
sec1 = HW_DIR/'Contents'/'section1.xml'

update = json.loads(Path('/root/renewal_update.json').read_text(encoding='utf-8'))
followups = []
with open('/root/followups.csv', newline='', encoding='utf-8') as f:
    r = csv.DictReader(f)
    for row in r:
        followups.append((int(row['sequence']), row['item']))
followups.sort(key=lambda x: x[0])
followup_texts = [f"{seq}. {item}" for seq, item in followups]

HP_NS = 'http://www.hancom.co.kr/hwpml/2010/HWPML'
NS = {'hp': HP_NS}
ET.register_namespace('hp', HP_NS)

APPENDIX_SENT = '이 부록 문단은 그대로 유지해야 합니다.'


def para_text(p):
    return ''.join((t.text or '') for t in p.findall('.//hp:t', NS))


def ensure_first_run_and_t(p):
    run = p.find('hp:run', NS)
    if run is None:
        run = ET.SubElement(p, f'{{{HP_NS}}}run')
    t = run.find('hp:t', NS)
    if t is None:
        t = ET.SubElement(run, f'{{{HP_NS}}}t')
    return run, t


def set_paragraph_text(p, new_text):
    # Preserve p attributes; keep first run; wipe other runs/t nodes.
    run, t = ensure_first_run_and_t(p)
    t.text = new_text

    # Remove any other <hp:t> in the first run after the first one.
    first_t_seen = False
    for child in list(run):
        if child.tag == f'{{{HP_NS}}}t':
            if not first_t_seen:
                first_t_seen = True
                continue
            run.remove(child)

    # Remove any other runs entirely
    for other_run in list(p.findall('hp:run', NS)):
        if other_run is run:
            continue
        p.remove(other_run)


def remove_layout_cache(p):
    # Remove linesegarray/lineseg anywhere under paragraph.
    parent = {c: par for par in p.iter() for c in list(par)}
    targets = []
    for el in p.iter():
        if el.tag in (f'{{{HP_NS}}}linesegarray', f'{{{HP_NS}}}lineseg'):
            targets.append(el)
    for el in targets:
        par = parent.get(el)
        if par is not None:
            par.remove(el)


def update_section0():
    tree = ET.parse(sec0)
    root = tree.getroot()

    modified = []

    for p in root.findall('.//hp:p', NS):
        txt = para_text(p)
        if APPENDIX_SENT in txt:
            continue

        if txt.startswith('고객사:'):
            set_paragraph_text(p, f"고객사: {update['customer']}")
            modified.append(p)
        elif txt.startswith('현 담당자:'):
            set_paragraph_text(p, f"현 담당자: {update['owner_name']}")
            modified.append(p)
        elif txt.startswith('갱신 윈도우:'):
            set_paragraph_text(p, f"갱신 윈도우: {update['window_start']} ~ {update['window_end']}")
            modified.append(p)
        elif txt.startswith('가격 메모:'):
            set_paragraph_text(p, f"가격 메모: {update['note']}")
            modified.append(p)

    # Table cell values by exact text match
    for t in root.findall('.//hp:t', NS):
        if (t.text or '') == 'Standard-18M':
            t.text = update['band']
            # mark its paragraph as modified
            par = t
            while par is not None and par.tag != f'{{{HP_NS}}}p':
                par = next((pp for pp in root.iter() if False), None)  # unreachable
        if (t.text or '') == 'ops-old@northwind.example':
            t.text = update['escalation_email']

    # Mark paragraphs containing updated band/escalation email
    for p in root.findall('.//hp:p', NS):
        txt = para_text(p)
        if txt == update['band'] or txt == update['escalation_email']:
            # only mark if it used to have layout cache (safe)
            if p not in modified:
                modified.append(p)

    for p in modified:
        remove_layout_cache(p)

    tree.write(sec0, encoding='UTF-8', xml_declaration=True)


def update_section1():
    tree = ET.parse(sec1)
    root = tree.getroot()

    modified = []

    # Update follow-up paragraphs: find those containing 'old follow-up'
    old_follow_ps = [p for p in root.findall('.//hp:p', NS) if 'old follow-up' in para_text(p)]
    old_follow_ps.sort(key=lambda p: int(p.get('id')) if (p.get('id') or '').isdigit() else 10**9)

    # Adjust count if needed
    if len(followup_texts) > len(old_follow_ps):
        # clone last follow-up paragraph structure if we need more
        if not old_follow_ps:
            raise RuntimeError('No existing follow-up paragraphs found to clone')
        template = old_follow_ps[-1]
        import copy
        for _ in range(len(followup_texts) - len(old_follow_ps)):
            new_p = copy.deepcopy(template)
            # clear ids if present to avoid duplicates; keep existing if verifier relies? safer to assign next.
            # In this tiny file, ids are sequential; extend.
            ids = [int(p.get('id')) for p in root.findall('.//hp:p', NS) if (p.get('id') or '').isdigit()]
            next_id = max(ids) + 1 if ids else 999
            new_p.set('id', str(next_id))
            # insert after template
            idx = list(root).index(template)
            root.insert(idx+1, new_p)
            old_follow_ps.append(new_p)
            template = new_p

    if len(followup_texts) < len(old_follow_ps):
        # remove excess follow-up paragraphs (from end)
        for p in old_follow_ps[len(followup_texts):][::-1]:
            root.remove(p)
        old_follow_ps = old_follow_ps[:len(followup_texts)]

    for p, text in zip(old_follow_ps, followup_texts):
        if APPENDIX_SENT in para_text(p):
            continue
        set_paragraph_text(p, text)
        modified.append(p)

    # Update renewal window confirmation paragraph
    for p in root.findall('.//hp:p', NS):
        txt = para_text(p)
        if APPENDIX_SENT in txt:
            continue
        if txt.startswith('갱신 윈도우 확인:'):
            set_paragraph_text(p, f"갱신 윈도우 확인: {update['window_start']} ~ {update['window_end']}")
            modified.append(p)

    for p in modified:
        remove_layout_cache(p)

    tree.write(sec1, encoding='UTF-8', xml_declaration=True)


update_section0()
update_section1()
print('Updated XML files written.')
print('Followups applied:', followup_texts)
